mapper.update:
		UPDATE CRM_AS_MGT
		SET 
              PROC_STATUS 		= #{proc_status, jdbcType=VARCHAR}
            , PROC_DT 			= #{proc_dt, jdbcType=VARCHAR}
            , ACTION_TYPE 		= #{action_type, jdbcType=VARCHAR}
            , ACTION_CONTENT 	= #{action_content, jdbcType=VARCHAR}
            , ASSIGN_ID			= #{assign_id, jdbcType=VARCHAR}
            , ATTACH_SEQ2 		= #{attach_seq2,  jdbcType=INTEGER}
            , CALL_CONTENT		= #{call_content, jdbcType=VARCHAR}	
		WHERE 1 = 1
		    AND AS_NO  = #{as_no}
